import type { EventKind } from '../calendar';
import { getPreset, PRESET_IDS } from '../presets';
import { clockOfSessionMinute } from '../time';
import type { Expr, Outcome, QueryError } from './ast';
import { type OutcomeWindow, TypeChecker, collectValues, latest, outcomeWindow } from './check';
import type { Tok } from './lexer';
import { lineCol } from './lexer';
import { type ParamDecl, type ParamEnv, type ParamUnit, type RawError, parseText, suggest } from './parser';
import { renderExpr, renderOutcome } from './render';

export interface QueryInput {
  setup: string;
  outcome: string;
  params?: Record<string, number>;
  /**
   * Units of parameters declared outside a preset (a query document's `param:` lines). An
   * extension: parseQueryDocument fills it so `$gap` declared as `0.3%` keeps its percent.
   */
  paramUnits?: Record<string, ParamUnit>;
  /**
   * An extension: the preset whose parameter declarations these texts use (a query document
   * that names a preset and rewrites one of its texts). runSetupOdds and buildHandoff read it.
   */
  preset?: string | null;
}

export interface Token {
  part: 'setup' | 'outcome';
  kind: 'keyword' | 'name' | 'field' | 'number' | 'unit' | 'time' | 'duration' | 'param' | 'operator' | 'punct' | 'error';
  offset: number;
  length: number;
}

export type QueryWindow = { kind: 'event'; start: string; end: string; barMinutes: number } | { kind: 'state'; knownAt: string };

export interface ParsedQueryInternal {
  setup: Expr;
  outcome: Outcome;
  decision: number;
  window: OutcomeWindow;
  params: Record<string, number>;
  preset: string | null;
  readsVolume: boolean;
  eventKinds: EventKind[];
  tickSize: number | null;
}

export interface ParsedQuery {
  setup: string;
  outcome: string;
  decisionTime: string;
  window: QueryWindow;
  /** internal: the checked trees and their analysis */
  readonly internal: ParsedQueryInternal;
}

export type QueryParseResult =
  | { ok: true; query: ParsedQuery; warnings: { code: string; message: string }[]; tokens: Token[] }
  | { ok: false; errors: QueryError[]; tokens: Token[] };

export interface ParseQueryOptions {
  tickSize?: number;
  preset?: string;
  /** characters per text; 2,000 unless a surface raises it */
  maxChars?: number;
}

const DURATION_WORDS = new Set(['m', 'min', 'mins', 'minute', 'minutes', 'h', 'hr', 'hrs', 'hour', 'hours']);
const PRICE_UNIT_WORDS = new Set(['pt', 'pts', 'point', 'points', 'tick', 'ticks']);
const KEYWORD_WORDS = new Set([
  'all', 'and', 'or', 'not', 'between', 'in', 'of', 'touches', 'trades', 'closes', 'above', 'below', 'before', 'then', 'from', 'by', 'within', 'on', 'session_close',
]);

function classify(toks: Tok[], part: 'setup' | 'outcome', error: RawError | null): Token[] {
  const out: Token[] = [];
  for (let i = 0; i < toks.length; i++) {
    const t = toks[i];
    if (t.type === 'EOF') continue;
    const prev = i > 0 ? toks[i - 1] : null;
    const next = toks[i + 1];
    let kind: Token['kind'];
    switch (t.type) {
      case 'TIME':
        kind = 'time';
        break;
      case 'NUMBER':
        kind = next && next.type === 'IDENT' && DURATION_WORDS.has(next.v) ? 'duration' : 'number';
        break;
      case 'PERCENT':
        kind = 'unit';
        break;
      case 'PARAM':
        kind = 'param';
        break;
      case 'OP':
        kind = 'operator';
        break;
      case 'PUNCT':
        kind = 'punct';
        break;
      default:
        if (prev && prev.type === 'PUNCT' && prev.v === '.') kind = 'field';
        else if (prev && (prev.type === 'NUMBER' || prev.type === 'PARAM') && (PRICE_UNIT_WORDS.has(t.v) || DURATION_WORDS.has(t.v))) kind = 'unit';
        else if (KEYWORD_WORDS.has(t.v) || (t.v === 'close' && prev && prev.type === 'IDENT' && prev.v === 'by')) kind = 'keyword';
        else kind = 'name';
    }
    out.push({ part, kind, offset: t.offset, length: t.length });
  }
  if (error && !out.some((x) => x.offset === error.offset)) out.push({ part, kind: 'error', offset: error.offset, length: error.length });
  else if (error) for (const x of out) if (x.offset === error.offset) x.kind = 'error';
  return out.sort((a, b) => a.offset - b.offset);
}

function toQueryError(e: RawError, part: QueryError['part'], text: string): QueryError {
  const { line, column } = lineCol(text, e.offset);
  return { code: e.code, part, offset: e.offset, length: e.length, line, column, message: e.message };
}

function presetError(id: string): QueryError {
  return {
    code: 'E_UNKNOWN_PRESET',
    part: 'document',
    offset: 0,
    length: Math.max(1, id.length),
    line: 1,
    column: 1,
    message: `There is no preset '${id}'.${suggest(id, PRESET_IDS)}`,
  };
}

const DEFAULT_MAX_CHARS = 2000;

export function parseQuery(input: QueryInput, options: { tickSize?: number; preset?: string; maxChars?: number } = {}): QueryParseResult {
  const presetId = options.preset ?? null;
  const preset = presetId === null ? null : getPreset(presetId);
  if (presetId !== null && !preset) return { ok: false, errors: [presetError(presetId)], tokens: [] };

  // ---- parameters
  const decls = new Map<string, ParamDecl>();
  const values = new Map<string, number>();
  const paramErrors: QueryError[] = [];
  if (preset)
    for (const p of preset.params) {
      decls.set(p.name, { unit: p.unit, min: p.min, max: p.max, source: 'preset' });
      values.set(p.name, p.default);
    }
  for (const [rawName, unit] of Object.entries(input.paramUnits ?? {})) {
    const name = rawName.toLowerCase();
    if (!decls.has(name)) decls.set(name, { unit, min: null, max: null, source: 'document' });
  }
  for (const rawName of Object.keys(input.params ?? {}).sort()) {
    const name = rawName.toLowerCase().replace(/^\$/, '');
    const v = input.params![rawName];
    const d = decls.get(name);
    if (!d) decls.set(name, { unit: 'none', min: null, max: null, source: 'map' });
    const min = d?.min ?? null;
    const max = d?.max ?? null;
    if (typeof v !== 'number' || !Number.isFinite(v) || (min !== null && v < min) || (max !== null && v > max)) {
      paramErrors.push({
        code: 'E_PARAM_RANGE',
        part: 'params',
        offset: 0,
        length: 1,
        line: 1,
        column: 1,
        message: `The parameter $${name} must be from ${min ?? -Number.MAX_VALUE} to ${max ?? Number.MAX_VALUE}; got ${String(v)}.`,
      });
      continue;
    }
    values.set(name, v);
  }
  const env: ParamEnv = { values, decls, used: new Set() };
  const maxChars = options.maxChars ?? DEFAULT_MAX_CHARS;

  const sp = parseText(input.setup, 'setup', env, maxChars);
  const op = parseText(input.outcome, 'outcome', env, maxChars);
  const tokens = [...classify(sp.toks, 'setup', sp.syntax), ...classify(op.toks, 'outcome', op.syntax)];
  const syntax: QueryError[] = [];
  if (sp.syntax) syntax.push(toQueryError(sp.syntax, 'setup', input.setup));
  if (op.syntax) syntax.push(toQueryError(op.syntax, 'outcome', input.outcome));
  if (syntax.length) return { ok: false, errors: syntax, tokens };

  const setup = sp.node as Expr;
  const outcome = op.node as Outcome;
  const setupErrors: RawError[] = [...sp.parser!.checks];
  const outcomeErrors: RawError[] = [...op.parser!.checks];

  // ---- types
  const tcS = new TypeChecker();
  if (setup.t !== 'all') {
    const first = sp.toks[0];
    tcS.requireBool(setup, { offset: first.offset, length: input.setup.trimEnd().length - first.offset }, 'setup');
  }
  setupErrors.push(...tcS.errors);
  const tcO = new TypeChecker();
  if (outcome.form === 'state') tcO.requireBool(outcome.expr, outcome.span, 'outcome');
  else {
    tcO.requirePrice(outcome.first.level, outcome.first.levelSpan);
    if (outcome.second) tcO.requirePrice(outcome.second.level, outcome.second.levelSpan);
  }
  outcomeErrors.push(...tcO.errors);

  // ---- ticks
  const tick = options.tickSize;
  const tickOk = typeof tick === 'number' && Number.isFinite(tick) && tick > 0;
  for (const [p, errs] of [[sp.parser!, setupErrors], [op.parser!, outcomeErrors]] as const)
    if (!tickOk)
      for (const s of p.tickUnits)
        errs.push({ code: 'E_TICK_SIZE', offset: s.offset, length: s.length, message: 'Ticks need a tick size. Set the tick size for this run, or write the distance in points.' });

  // ---- known-at, decision time, the window
  const setupValues = collectValues(setup);
  const setupLatest = latest(setupValues);
  const decision = setupLatest ? setupLatest.knownAt : 0;
  const winErrors: RawError[] = [];
  const win = outcomeWindow(outcome, decision, setupLatest, winErrors);
  // the window's static checks are meaningful only once the outcome's own arguments are valid
  if (op.parser!.checks.length === 0) outcomeErrors.push(...winErrors);

  const errors = [
    ...setupErrors.sort((a, b) => a.offset - b.offset).map((e) => toQueryError(e, 'setup', input.setup)),
    ...outcomeErrors.sort((a, b) => a.offset - b.offset).map((e) => toQueryError(e, 'outcome', input.outcome)),
    ...paramErrors,
  ];
  if (errors.length) return { ok: false, errors, tokens };

  // ---- warnings
  const warnings: { code: string; message: string }[] = [];
  for (const b of [...sp.parser!.betweens, ...op.parser!.betweens]) {
    if (b.t !== 'between') continue;
    const { a, b: hi } = b;
    if (a.t === 'num' && hi.t === 'num' && !a.of && !hi.of && a.unit === hi.unit && a.value > hi.value)
      warnings.push({ code: 'W_EMPTY_BETWEEN', message: `${renderExpr(b)} can never be true: the lower end is above the upper end.` });
  }

  // ---- what the query reads
  const outVals = outcome.form === 'state' ? collectValues(outcome.expr) : [...collectValues(outcome.first.level), ...(outcome.second ? collectValues(outcome.second.level) : [])];
  const all = [...setupValues, ...outVals];
  const readsVolume = all.some((v) => v.expr.t === 'win' && v.expr.field === 'volume');
  const kinds = new Set<EventKind>();
  for (const v of all) {
    if (v.expr.t === 'event') v.expr.kinds.forEach((k) => kinds.add(k));
    if (v.expr.t === 'days_since' || v.expr.t === 'days_to') kinds.add(v.expr.kind);
  }
  const params: Record<string, number> = {};
  const names = new Set<string>(env.used);
  if (preset) preset.params.forEach((p) => names.add(p.name));
  for (const n of [...names].sort()) if (values.has(n)) params[n] = values.get(n)!;

  const setupText = renderExpr(setup);
  const outcomeText = renderOutcome(outcome);
  const window: QueryWindow =
    win.kind === 'state'
      ? { kind: 'state', knownAt: clockOfSessionMinute(win.knownAt) }
      : {
          kind: 'event',
          start: clockOfSessionMinute(win.start),
          end: win.endKind === 'close' || win.endKind === 'default' ? 'close' : win.endKind === 'session_close' ? 'session_close' : clockOfSessionMinute(win.end),
          barMinutes: win.barMinutes,
        };
  const query: ParsedQuery = {
    setup: setupText,
    outcome: outcomeText,
    decisionTime: clockOfSessionMinute(decision),
    window,
    internal: {
      setup,
      outcome,
      decision,
      window: win,
      params,
      preset: presetId,
      readsVolume,
      eventKinds: [...kinds],
      tickSize: tickOk ? tick! : null,
    },
  };
  return { ok: true, query, warnings, tokens };
}
